import logging
import re

from taf.hw.rf_attenuator.utils.telnet import TelnetClient
from taf.hw.rf_attenuator.attenuator_class import Attenuator
from taf.hw.rf_attenuator.exceptions import (NotEnoughParametersProvided,
                                             AttenuationSetError,
                                             AttenuatorCmdError,
                                             AttenuationReadError)


class TopYoung(Attenuator):
    MAX_SUPPORTED_ATTENUATION = 120
    MIN_SUPPORTED_ATTENUATION = 0
    _SET_CMD = 'SET:{}:{}'
    _SET_RES_OK = r'RESET:{}:OK'
    _SET_RES_FAIL = r'RESET:\d+:FAIL'
    _READ_CMD = 'READ:{}'
    _READ_RES_OK = r'REREAD:{}:(\d+)'
    _READ_RES_FAIL = r'REREAD:\d+:FAIL'
    _CMD_ERR = 'CMDERR'

    def __init__(self, ip, port=23, min_attenuation=None, max_attenuation=None):
        super(TopYoung, self).__init__()
        self._ip = ip
        self._port = port
        self._telnet = TelnetClient()
        self._attenuation_port_numbers = None
        self.min_attenuation = self._validate_min_attenuation(min_attenuation, self.MIN_SUPPORTED_ATTENUATION)
        self.max_attenuation = self._validate_max_attenuation(max_attenuation, self.MAX_SUPPORTED_ATTENUATION)

    def connect(self, **kwargs):
        """
        Establish connection with attenuation controller
        allowing to change attenuation on specific RF-channel of that device
        """
        self._telnet.connect(self._ip, self._port)
        logging.info('Connection to TopYoung rf_attenuator established.')
        if 'ports' in kwargs.keys():
            rf_ports = kwargs['ports']
            self._attenuation_port_numbers = rf_ports if isinstance(rf_ports, list) else rf_ports.keys()
        else:
            raise NotEnoughParametersProvided('No available channels.')

    def disconnect(self, **kwargs):
        """
        Release connection with attenuation controller
        """
        self._telnet.close_connection()
        logging.warning('Connection to TopYoung rf_attenuator is not established.')

    def _is_channel_valid(self, rf_port_address):
        if rf_port_address not in self._attenuation_port_numbers:
            msg = 'Channel invalid, {} not in set {}'.format(
                rf_port_address,
                self._attenuation_port_numbers,
            )
            raise AttenuationReadError(msg)
        logging.info('Channel valid, {} in set {}.'.format(rf_port_address, self._attenuation_port_numbers))

    def _set_single_port_decibel_attenuation(self, rf_port_address, attenuation_value_db):
        attenuation_value_db = int(attenuation_value_db)
        self._is_channel_valid(rf_port_address)
        res_cmd = self._write_and_read(self._SET_CMD.format(rf_port_address, attenuation_value_db))
        self._verify_set_attenuation_command_response(rf_port_address, res_cmd)
        logging.info('Channel {} attenuation value is set to {} dB.'.format(rf_port_address, attenuation_value_db))

    def _write_and_read(self, cmd):
        cmd_result = self._telnet.read_command_output(command=cmd, read_method='until')
        logging.debug('The response of command:\n {}'.format(cmd_result))
        return cmd_result

    def _verify_set_attenuation_command_response(self, rf_port_address, res):
        if re.search(self._SET_RES_OK.format(rf_port_address), res):
            return
        self._check_if_set_command_failed(self._SET_RES_FAIL, res)
        self._check_if_command_error(self._CMD_ERR, res)

    @staticmethod
    def _check_if_read_command_failed(pattern, res):
        if re.search(pattern, res):
            raise AttenuationReadError('Please check device status.')

    @staticmethod
    def _check_if_set_command_failed(pattern, res):
        if re.search(pattern, res):
            raise AttenuationSetError('Please check device status.')

    @staticmethod
    def _check_if_command_error(pattern, res):
        if re.search(pattern, res):
            raise AttenuatorCmdError('Please check the format and parameters of the command.')

    def read_port_attenuation(self, port):
        self._is_channel_valid(port)
        res_cmd = self._write_and_read(self._READ_CMD.format(port))
        return self._verify_read_attenuation_command_response(port, res_cmd)

    def _verify_read_attenuation_command_response(self, rf_port_address, res):
        self._check_if_read_command_failed(self._READ_RES_FAIL, res)
        self._check_if_command_error(self._CMD_ERR, res)
        re_out = re.search(self._READ_RES_OK.format(rf_port_address), res)
        if re_out:
            value_read = re_out.groups()[0]
            logging.info('Channel {} attenuation value is {} dB.'.format(rf_port_address, value_read))
            return int(value_read)
        raise AttenuationReadError

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        for index, rf_port_addresse in enumerate(rf_port_addresses):
            self._set_single_port_decibel_attenuation(rf_port_addresse, attenuation_values_db[index])
